from decimal import Decimal, ROUND_HALF_UP
from typing import Any


_CENT = Decimal("0.01")
_ZERO = Decimal("0")


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _decimal_or_zero(value: Any) -> Decimal:
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    result = order.copy()

    if new_status == "X":
        result["STAT_CD"] = "X"
        return result, ["ORD_CANC_INV"], ["credit_note"]

    if new_status == "I":
        return result, [], []

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    result_order = order.copy()
    result_lines = [line.copy() for line in lines]

    if order.get("STAT_CD") in {"I", "X"}:
        return result_order, result_lines, []

    total = _ZERO

    for result_line in result_lines:
        if result_line.get("DEL_FLG", "") == "Y":
            continue

        quantity = _decimal_or_zero(result_line.get("QTY"))
        unit_price = _decimal_or_zero(result_line.get("UNIT_PRC"))
        extended_amount = _round_cents(quantity * unit_price)

        result_line["EXT_AMT"] = float(extended_amount)
        total += extended_amount

    discount_percent = _decimal_or_zero(order.get("DISC_PCT"))
    recomputed_total = _round_cents(
        total * (Decimal("100") - discount_percent) / Decimal("100")
    )

    stored_total = _decimal_or_zero(order.get("TOT_AMT"))
    audits = ["ORD_RETOTAL"] if recomputed_total != stored_total else []

    result_order["TOT_AMT"] = float(recomputed_total)
    return result_order, result_lines, audits
